package com.yeyamo_mobile.api.analytics_service.controller;
import java.util.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Component;
/** Applies territorial scopes carried by the trusted admin token. SUPER_ADMIN remains global. */
@Component class TerritorialAnalyticsAccess {
 boolean global(Authentication a){return a!=null&&a.getAuthorities().stream().anyMatch(x->"ROLE_SUPER_ADMIN".equals(x.getAuthority()));}
 Set<String> countries(Authentication a){if(global(a))return Set.of();if(!(a instanceof JwtAuthenticationToken jwt))throw new AccessDeniedException("Territorial admin scope is required");Object raw=jwt.getToken().getClaims().get("adminCountries");Set<String> result=new LinkedHashSet<>();if(raw instanceof Collection<?> c)c.forEach(v->add(result,String.valueOf(v)));else if(raw!=null)for(String v:String.valueOf(raw).split(","))add(result,v);if("GLOBAL".equals(jwt.getToken().getClaimAsString("adminScope")))return Set.of();if(result.isEmpty())throw new AccessDeniedException("Territorial admin scope is required");return Set.copyOf(result);}void requireCountry(Authentication a,String country){if(global(a))return;if(!countries(a).contains(country.toUpperCase(Locale.ROOT)))throw new AccessDeniedException("Country is outside administrator scope");}private void add(Set<String> r,String v){if(v!=null&&v.trim().matches("[A-Za-z]{2}"))r.add(v.trim().toUpperCase(Locale.ROOT));}}
